import {ArrowLeft,CalendarDays,Car,CheckCircle2,Clock3,Edit3,Euro,Mail,MessageCircle,NotebookPen,Phone,Plus,Save,Search,UserRound,X} from 'lucide-react'
import {useEffect,useMemo,useState} from 'react'
import {clearCustomerNextAction,logCustomerInteraction,saveCustomerNextAction} from '../lib/api'
import {saveCustomer,saveCustomerInterest} from '../lib/customerApi'
import {Customer360Overview} from '../components/Customer360Overview'
import type {Customer,CustomerDraft,CustomerInterest,CustomerInterestDraft,TenantData} from '../types'

const EMPTY_CUSTOMER:CustomerDraft={firstName:'',lastName:'',phone:'',email:'',fiscalCode:'',status:'LEAD',source:'',notes:'',preferredContact:''}
const EMPTY_INTEREST:CustomerInterestDraft={vehicleId:'',status:'INTERESSATO',offerAmount:'',note:''}
const INTEREST_STATUSES=['INTERESSATO','TEST_DRIVE','OFFERTA','TRATTATIVA','VINTA','PERSA']
const nameOf=(c:Customer)=>[c.first_name,c.last_name].filter(Boolean).join(' ')||'Cliente'
const vehicleName=(vehicle?:TenantData['vehicles'][number])=>vehicle?[vehicle.brand,vehicle.model,vehicle.version].filter(Boolean).join(' '):'Auto non disponibile'
const money=(value?:number|null)=>value===null||value===undefined?'—':new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(value))
const localInput=(value?:string|null)=>{if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
const dueLabel=(value?:string|null)=>{if(!value)return 'Nessuna scadenza';const d=new Date(value);if(Number.isNaN(d.getTime()))return 'Data non valida';const today=new Date();const same=d.toDateString()===today.toDateString();const overdue=d.getTime()<Date.now()&&!same;return `${overdue?'SCADUTA · ':same?'OGGI · ':''}${d.toLocaleString('it-IT',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}`}
const waNumber=(phone:string)=>{let digits=phone.replace(/\D/g,'');if(digits.startsWith('00'))digits=digits.slice(2);if(digits.startsWith('39'))return digits;if(digits.startsWith('3'))return `39${digits}`;return digits}

export function ClientsPage({data,writable,onRefresh,focusCustomerId,focusKey=0,onFocusConsumed,onOpenVehicle,onOpenCalendar,onOpenSales}:{data:TenantData;writable:boolean;onRefresh:()=>Promise<void>;focusCustomerId?:string|null;focusKey?:number;onFocusConsumed?:()=>void;onOpenVehicle:(id:string)=>void;onOpenCalendar:(id:string)=>void;onOpenSales:(id:string)=>void}){
  const [query,setQuery]=useState('')
  const [selectedId,setSelectedId]=useState<string|null>(null)
  const [editorMode,setEditorMode]=useState<'create'|'edit'|null>(null)
  const [customerDraft,setCustomerDraft]=useState<CustomerDraft>(EMPTY_CUSTOMER)
  const [nextStep,setNextStep]=useState('')
  const [nextAt,setNextAt]=useState('')
  const [interaction,setInteraction]=useState('')
  const [interestEditing,setInterestEditing]=useState<string|null>(null)
  const [interestDraft,setInterestDraft]=useState<CustomerInterestDraft>(EMPTY_INTEREST)
  const [saving,setSaving]=useState(false)
  const [error,setError]=useState('')

  const rows=useMemo(()=>data.customers
    .filter(c=>!c.deleted_at)
    .filter(c=>`${c.first_name||''} ${c.last_name||''} ${c.phone||''} ${c.email||''} ${c.next_step||''} ${c.fiscal_code||''}`.toLowerCase().includes(query.toLowerCase()))
    .sort((a,b)=>{const ad=a.next_contact_at?new Date(a.next_contact_at).getTime():Number.MAX_SAFE_INTEGER;const bd=b.next_contact_at?new Date(b.next_contact_at).getTime():Number.MAX_SAFE_INTEGER;return ad-bd||nameOf(a).localeCompare(nameOf(b))}),[data.customers,query])
  const selected=selectedId?data.customers.find(c=>c.id===selectedId):undefined
  const customerInterests=selected?data.customerInterests.filter(i=>i.customer_id===selected.id):[]
  const customerInteractions=selected?data.customerInteractions.filter(i=>i.customer_id===selected.id).sort((a,b)=>new Date(b.happened_at||0).getTime()-new Date(a.happened_at||0).getTime()):[]
  const customerEvents=selected?data.calendarEvents.filter(e=>e.customer_id===selected.id).sort((a,b)=>new Date(a.starts_at||0).getTime()-new Date(b.starts_at||0).getTime()):[]
  const usedVehicleIds=new Set(customerInterests.map(i=>i.vehicle_id))
  const statuses=Array.from(new Set(['LEAD','CLIENTE','CHIUSO_VINTO','CHIUSO_PERSO',...data.customers.map(c=>c.status).filter(Boolean) as string[]]))

  const openCustomer=(c:Customer)=>{setSelectedId(c.id);setEditorMode(null);setNextStep(c.next_step||'');setNextAt(localInput(c.next_contact_at));setInteraction('');setInterestEditing(null);setInterestDraft(EMPTY_INTEREST);setError('')}
  useEffect(()=>{if(!focusCustomerId)return;const customer=data.customers.find(c=>c.id===focusCustomerId&&!c.deleted_at);if(customer){openCustomer(customer);onFocusConsumed?.()}},[focusCustomerId,focusKey,data.customers])
  const closeCustomer=()=>{setSelectedId(null);setEditorMode(null);setInterestEditing(null);setError('')}
  const startCreate=()=>{setSelectedId(null);setCustomerDraft(EMPTY_CUSTOMER);setEditorMode('create');setError('')}
  const startEdit=(c:Customer)=>{setCustomerDraft({firstName:c.first_name||'',lastName:c.last_name||'',phone:c.phone||'',email:c.email||'',fiscalCode:c.fiscal_code||'',status:c.status||'LEAD',source:c.source||'',notes:c.notes||'',preferredContact:c.preferred_contact||''});setEditorMode('edit');setError('')}
  const persistCustomer=async()=>{setSaving(true);setError('');try{const saved=await saveCustomer(customerDraft,editorMode==='edit'?selected?.id:undefined);await onRefresh();setSelectedId(saved.id);setEditorMode(null);setNextStep(saved.next_step||'');setNextAt(localInput(saved.next_contact_at))}catch(err){setError(err instanceof Error?err.message:'Errore salvataggio cliente')}finally{setSaving(false)}}
  const persistAction=async(c:Customer)=>{setSaving(true);setError('');try{await saveCustomerNextAction(c,{nextStep,nextContactAt:nextAt?new Date(nextAt).toISOString():null});await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Errore salvataggio')}finally{setSaving(false)}}
  const clearAction=async(c:Customer)=>{setSaving(true);setError('');try{await clearCustomerNextAction(c);setNextStep('');setNextAt('');await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Errore aggiornamento')}finally{setSaving(false)}}
  const log=async(c:Customer,channel:string,defaultText:string)=>{setSaving(true);setError('');try{await logCustomerInteraction(c,{channel,title:interaction.trim()||defaultText});setInteraction('');await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Errore registrazione contatto')}finally{setSaving(false)}}
  const startInterest=(interest?:CustomerInterest)=>{if(interest){setInterestEditing(interest.id);setInterestDraft({vehicleId:interest.vehicle_id,status:interest.status||'INTERESSATO',offerAmount:interest.offer_amount??'',note:interest.note||''})}else{setInterestEditing('new');setInterestDraft(EMPTY_INTEREST)}setError('')}
  const persistInterest=async()=>{if(!selected)return;setSaving(true);setError('');try{await saveCustomerInterest(selected,interestDraft,interestEditing&&interestEditing!=='new'?interestEditing:undefined);setInterestEditing(null);setInterestDraft(EMPTY_INTEREST);await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Errore salvataggio auto interessata')}finally{setSaving(false)}}

  return <>
    <div className="page-heading"><div><p className="eyebrow">CRM OPERATIVO</p><h1>Clienti</h1><p>Anagrafica, auto interessate, contatti e prossima azione in un’unica scheda.</p></div><div className="client-heading-actions"><div className="mini-stat"><span>DA RICHIAMARE</span><b>{data.customers.filter(c=>c.next_contact_at&&new Date(c.next_contact_at).getTime()<=Date.now()).length}</b></div>{writable&&<button className="primary-action" data-testid="new-customer" onClick={startCreate}><Plus/> Nuovo cliente</button>}</div></div>

    {error&&<div className="form-error customer-global-error">{error}</div>}

    {editorMode&&<section className="customer-editor" data-testid="customer-editor">
      <div className="customer-section-head"><div><p className="eyebrow">{editorMode==='create'?'NUOVO CLIENTE':'MODIFICA CLIENTE'}</p><h2>{editorMode==='create'?'Inserisci cliente':selected?nameOf(selected):'Cliente'}</h2></div><button className="icon-ghost" aria-label="Chiudi modifica" onClick={()=>setEditorMode(null)}><X/></button></div>
      <div className="customer-form-grid">
        <label><span>NOME *</span><input aria-label="NOME" disabled={saving} value={customerDraft.firstName} onChange={e=>setCustomerDraft({...customerDraft,firstName:e.target.value})}/></label>
        <label><span>COGNOME *</span><input aria-label="COGNOME" disabled={saving} value={customerDraft.lastName} onChange={e=>setCustomerDraft({...customerDraft,lastName:e.target.value})}/></label>
        <label><span>TELEFONO</span><input aria-label="TELEFONO" inputMode="tel" disabled={saving} value={customerDraft.phone||''} onChange={e=>setCustomerDraft({...customerDraft,phone:e.target.value})}/></label>
        <label><span>EMAIL</span><input aria-label="EMAIL" type="email" disabled={saving} value={customerDraft.email||''} onChange={e=>setCustomerDraft({...customerDraft,email:e.target.value})}/></label>
        <label><span>CODICE FISCALE</span><input aria-label="CODICE FISCALE" disabled={saving} value={customerDraft.fiscalCode||''} onChange={e=>setCustomerDraft({...customerDraft,fiscalCode:e.target.value})}/></label>
        <label><span>STATO</span><select aria-label="STATO CLIENTE" disabled={saving} value={customerDraft.status||'LEAD'} onChange={e=>setCustomerDraft({...customerDraft,status:e.target.value})}>{statuses.map(s=><option key={s} value={s}>{s.replaceAll('_',' ')}</option>)}</select></label>
        <label><span>CONTATTO PREFERITO</span><select aria-label="CONTATTO PREFERITO" disabled={saving} value={customerDraft.preferredContact||''} onChange={e=>setCustomerDraft({...customerDraft,preferredContact:e.target.value})}><option value="">Non indicato</option><option value="TELEFONO">Telefono</option><option value="WHATSAPP">WhatsApp</option><option value="EMAIL">Email</option></select></label>
        <label><span>PROVENIENZA</span><input aria-label="PROVENIENZA" disabled={saving} placeholder="Es. AutoScout, passaparola, showroom" value={customerDraft.source||''} onChange={e=>setCustomerDraft({...customerDraft,source:e.target.value})}/></label>
        <label className="wide"><span>NOTE CLIENTE</span><textarea aria-label="NOTE CLIENTE" disabled={saving} rows={3} value={customerDraft.notes||''} onChange={e=>setCustomerDraft({...customerDraft,notes:e.target.value})}/></label>
      </div>
      <div className="workbench-actions"><button data-testid="customer-save" disabled={saving||!writable} onClick={()=>void persistCustomer()}><Save/> {saving?'Salvataggio…':'Salva cliente'}</button><button className="ghost" onClick={()=>setEditorMode(null)}><X/> Annulla</button></div>
    </section>}

    {!editorMode&&selected&&<section className="customer-detail" data-testid="customer-detail">
      <div className="customer-detail-head"><button className="back-customer" onClick={closeCustomer}><ArrowLeft/> Clienti</button><div className="customer-title"><div className="customer-avatar large"><UserRound/></div><div><div className="customer-title-line"><h2>{nameOf(selected)}</h2><span className="customer-status">{selected.status?.replaceAll('_',' ')||'LEAD'}</span></div><p>{selected.next_step||'Nessuna prossima azione'} · {dueLabel(selected.next_contact_at)}</p></div></div><div className="customer-head-actions">{selected.phone&&<a title="Chiama cliente" href={`tel:${selected.phone}`}><Phone/></a>}{selected.phone&&<a title="Apri WhatsApp" href={`https://wa.me/${waNumber(selected.phone)}`} target="_blank" rel="noreferrer"><MessageCircle/></a>}{selected.email&&<a title="Scrivi email" href={`mailto:${selected.email}`}><Mail/></a>}{writable&&<button title="Modifica cliente" onClick={()=>startEdit(selected)}><Edit3/></button>}</div></div>

      <Customer360Overview customer={selected} data={data} onOpenVehicle={onOpenVehicle} onOpenCalendar={onOpenCalendar} onOpenSales={onOpenSales}/>

      <div className="customer-dashboard-grid">
        <article className="customer-panel identity-panel"><div className="panel-title"><UserRound/><div><b>Dati cliente</b><small>Contatti e informazioni utili</small></div></div><dl><div><dt>Telefono</dt><dd>{selected.phone||'—'}</dd></div><div><dt>Email</dt><dd>{selected.email||'—'}</dd></div><div><dt>Codice fiscale</dt><dd>{selected.fiscal_code||'—'}</dd></div><div><dt>Preferenza</dt><dd>{selected.preferred_contact||'—'}</dd></div><div><dt>Provenienza</dt><dd>{selected.source||'—'}</dd></div></dl>{selected.notes&&<p className="customer-notes">{selected.notes}</p>}</article>

        <article className="customer-panel next-panel"><div className="panel-title"><Clock3/><div><b>Prossima azione</b><small>La cosa che non deve essere dimenticata</small></div></div>{!writable&&<div className="inline-note">Profilo in sola lettura.</div>}<div className="workbench-grid one"><label><span>COSA FARE</span><input disabled={!writable||saving} value={nextStep} onChange={e=>setNextStep(e.target.value)} placeholder="Es. richiamare per proposta Golf"/></label><label><span>QUANDO</span><input disabled={!writable||saving} type="datetime-local" value={nextAt} onChange={e=>setNextAt(e.target.value)}/></label></div><div className="workbench-actions"><button disabled={!writable||saving||!nextStep.trim()} onClick={()=>void persistAction(selected)}><Save/> Salva</button>{selected.next_step&&<button className="ghost" disabled={!writable||saving} onClick={()=>void clearAction(selected)}><CheckCircle2/> Fatto</button>}</div></article>
      </div>

      <article className="customer-panel interest-panel"><div className="customer-section-head"><div className="panel-title"><Car/><div><b>Auto d’interesse</b><small>Veicoli, fase trattativa e offerta cliente</small></div></div>{writable&&!interestEditing&&<button className="soft-action" data-testid="add-interest" onClick={()=>startInterest()}><Plus/> Aggiungi auto</button>}</div>
        {interestEditing&&<div className="interest-editor" data-testid="interest-editor"><div className="interest-grid"><label><span>AUTO</span><select aria-label="AUTO INTERESSATA" disabled={saving||interestEditing!=='new'} value={interestDraft.vehicleId} onChange={e=>setInterestDraft({...interestDraft,vehicleId:e.target.value})}><option value="">Seleziona auto…</option>{data.vehicles.filter(v=>!v.deleted_at&&(!usedVehicleIds.has(v.id)||v.id===interestDraft.vehicleId)).map(v=><option key={v.id} value={v.id}>{vehicleName(v)}{v.plate?` · ${v.plate}`:''}</option>)}</select></label><label><span>FASE</span><select aria-label="FASE INTERESSE" disabled={saving} value={interestDraft.status||'INTERESSATO'} onChange={e=>setInterestDraft({...interestDraft,status:e.target.value})}>{INTEREST_STATUSES.map(s=><option key={s} value={s}>{s.replaceAll('_',' ')}</option>)}</select></label><label><span>OFFERTA CLIENTE €</span><input aria-label="OFFERTA CLIENTE" inputMode="decimal" disabled={saving} value={interestDraft.offerAmount??''} onChange={e=>setInterestDraft({...interestDraft,offerAmount:e.target.value})}/></label><label className="wide"><span>NOTA</span><input aria-label="NOTA INTERESSE" disabled={saving} placeholder="Es. vuole permuta / attende finanziamento" value={interestDraft.note||''} onChange={e=>setInterestDraft({...interestDraft,note:e.target.value})}/></label></div><div className="workbench-actions"><button data-testid="interest-save" disabled={saving||!interestDraft.vehicleId} onClick={()=>void persistInterest()}><Save/> Salva interesse</button><button className="ghost" onClick={()=>{setInterestEditing(null);setInterestDraft(EMPTY_INTEREST)}}><X/> Annulla</button></div></div>}
        <div className="interest-list">{customerInterests.map(i=>{const v=data.vehicles.find(vehicle=>vehicle.id===i.vehicle_id);return <button key={i.id} className="interest-row" onClick={()=>writable&&startInterest(i)}><div className="interest-car"><Car/><div><b>{vehicleName(v)}</b><small>{v?.plate||v?.status||'Veicolo collegato'}</small></div></div><span className={`interest-status status-${(i.status||'INTERESSATO').toLowerCase()}`}>{(i.status||'INTERESSATO').replaceAll('_',' ')}</span><div className="interest-offer"><Euro/><b>{money(i.offer_amount)}</b><small>{i.note||'Nessuna nota'}</small></div>{writable&&<Edit3/>}</button>})}{!customerInterests.length&&!interestEditing&&<div className="empty-mini">Nessuna auto collegata. Aggiungila quando il cliente mostra interesse.</div>}</div>
      </article>

      <div className="customer-history-grid">
        <article className="customer-panel interaction-panel"><div className="panel-title"><MessageCircle/><div><b>Contatti</b><small>Registra subito ciò che è successo</small></div></div><div className="interaction-box customer-interaction"><label><span>NOTA RAPIDA</span><input disabled={!writable||saving} value={interaction} onChange={e=>setInteraction(e.target.value)} placeholder="Es. interessato, richiamare venerdì"/></label><div><button disabled={!writable||saving} onClick={()=>void log(selected,'TELEFONO','Contatto telefonico effettuato')}><Phone/> Chiamata</button><button disabled={!writable||saving} onClick={()=>void log(selected,'WHATSAPP','Contatto WhatsApp effettuato')}><MessageCircle/> WhatsApp</button><button disabled={!writable||saving} onClick={()=>void log(selected,'NOTE','Nota cliente registrata')}><NotebookPen/> Nota</button></div></div><div className="timeline">{customerInteractions.map(item=><div className="timeline-row" key={item.id}><span className="timeline-dot"/><div><b>{item.title||item.channel||'Contatto'}</b><small>{item.channel||'NOTE'} · {item.happened_at?new Date(item.happened_at).toLocaleString('it-IT',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'}</small></div></div>)}{!customerInteractions.length&&<div className="empty-mini">Nessun contatto registrato.</div>}</div></article>

        <article className="customer-panel appointments-panel"><div className="panel-title"><CalendarDays/><div><b>Appuntamenti</b><small>Impegni collegati a questo cliente</small></div></div><div className="customer-events">{customerEvents.slice(0,6).map(event=><div className="customer-event" key={event.id}><div className="event-date"><b>{event.starts_at?new Date(event.starts_at).toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit'}):'—'}</b><span>{event.starts_at?new Date(event.starts_at).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}):''}</span></div><div><b>{event.title||'Appuntamento'}</b><small>{event.event_type?.replaceAll('_',' ')||'APPUNTAMENTO'} · {event.status||'OPEN'}</small></div></div>)}{!customerEvents.length&&<div className="empty-mini">Nessun appuntamento collegato.</div>}</div></article>
      </div>
    </section>}

    {!editorMode&&!selected&&<><div className="toolbar"><label className="search-input"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Nome, telefono, email, codice fiscale…"/></label></div><div className="client-list">{rows.map(c=>{const interactions=data.customerInteractions.filter(x=>x.customer_id===c.id);const last=interactions.sort((a,b)=>new Date(b.happened_at||0).getTime()-new Date(a.happened_at||0).getTime())[0];const interests=data.customerInterests.filter(x=>x.customer_id===c.id);const vehicles=interests.map(i=>data.vehicles.find(v=>v.id===i.vehicle_id)).filter(Boolean);const due=c.next_contact_at?new Date(c.next_contact_at):null;const overdue=Boolean(due&&!Number.isNaN(due.getTime())&&due.getTime()<Date.now()&&due.toDateString()!==new Date().toDateString());return <article key={c.id} className={`client-card client-card-actionable ${overdue?'is-overdue':''}`}><button className="client-main" onClick={()=>openCustomer(c)}><div className="client-avatar"><UserRound/></div><div className="client-copy"><div className="client-name-line"><h3>{nameOf(c)}</h3><span>{c.status?.replaceAll('_',' ')||'LEAD'}</span></div><p>{vehicles.length?vehicles.slice(0,2).map(v=>vehicleName(v)).join(' · '):'Nessuna auto collegata'}</p><span className={`next-action ${overdue?'danger':''}`}><Clock3/>{c.next_step||'Imposta la prossima azione'} · {dueLabel(c.next_contact_at)}</span><small>{last?.happened_at?`Ultimo contatto ${new Date(last.happened_at).toLocaleDateString('it-IT')} · ${last.title||last.channel||'contatto'}`:'Nessun contatto registrato'}</small></div></button><div className="client-actions">{c.phone&&<a aria-label="Chiama" href={`tel:${c.phone}`}><Phone/></a>}{c.phone&&<a aria-label="WhatsApp" href={`https://wa.me/${waNumber(c.phone)}`} target="_blank" rel="noreferrer"><MessageCircle/></a>}</div></article>})}{!rows.length&&<div className="empty-state">Nessun cliente trovato.</div>}</div></>}
  </>
}
