import {config} from './config'
import {getSession,setSession} from './api'
import type {DocumentRecord,ExpenseConfirmDraft,SessionPayload} from '../types'

const JSON_HEADERS={'content-type':'application/json'}
const friendly:Record<string,string>={
  unauthorized:'Sessione scaduta. Accedi di nuovo.',not_dealer_member:'Utente non abilitato alla concessionaria.',dealer_access_locked:'Accesso concessionaria bloccato.',
  finance_documents_forbidden:'Questa sezione è riservata ad amministrazione e amministratore.',documents_write_required:'Non hai il permesso di caricare documenti.',
  file_too_large:'Il documento supera il limite di 20 MB.',empty_file:'Il file è vuoto.',file_signature_not_allowed:'Formato non supportato. Usa PDF, JPG, PNG, WEBP o HEIC.',
  file_type_mismatch:'Il formato reale del file non corrisponde all’estensione.',storage_upload_failed:'Caricamento non riuscito. Riprova.',file_not_in_cloud:'Il documento non è ancora stato caricato.',
  document_not_found:'Documento non trovato.',vehicle_required:'Seleziona l’auto a cui associare la spesa.',vehicle_not_found:'Auto non trovata.',invalid_amount:'Controlla l’importo.',invalid_date:'Controlla la data.'
}
async function parse<T>(res:Response):Promise<T>{const text=await res.text();let data:any=null;try{data=text?JSON.parse(text):null}catch{data=text}if(!res.ok){const code=String(data?.error||data?.message||`http_${res.status}`);throw new Error(friendly[code]||code)}return data as T}
async function liveSession(fallback?:SessionPayload){let session=getSession()||fallback;if(!session)throw new Error('Sessione richiesta');if(!session.expires_at||Date.now()/1000>session.expires_at-30){const data=await parse<SessionPayload&{expires_in?:number}>(await fetch(`${config.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{...JSON_HEADERS,apikey:config.supabasePublishableKey},body:JSON.stringify({refresh_token:session.refresh_token})}));session={...session,...data,expires_at:Math.floor(Date.now()/1000)+(data.expires_in||3600)};setSession(session)}return session}
async function authHeaders(fallback?:SessionPayload,json=true){const session=await liveSession(fallback);return {session,headers:{authorization:`Bearer ${session.access_token}`,'x-dealer-id':session.dealer.id,...(json?JSON_HEADERS:{})}}}
export async function listExpenseDocuments(session?:SessionPayload){const a=await authHeaders(session,false);return parse<{ok:true;documents:DocumentRecord[]}>(await fetch(`${config.documentsUrl}/list`,{headers:a.headers,cache:'no-store'}))}
export async function createExpenseDocument(file:File,session?:SessionPayload){const a=await authHeaders(session);return parse<{ok:true;document:DocumentRecord}>(await fetch(`${config.documentsUrl}/create`,{method:'POST',headers:a.headers,body:JSON.stringify({original_name:file.name||'documento',mime_type:file.type||null,size_bytes:file.size})}))}
export async function uploadExpenseDocument(documentId:string,file:File,session?:SessionPayload){const a=await authHeaders(session,false);return parse<{ok:true;object_key:string;size_bytes:number;mime_type:string}>(await fetch(`${config.documentsUrl}/file?document_id=${encodeURIComponent(documentId)}&file_name=${encodeURIComponent(file.name||'documento')}`,{method:'PUT',headers:{...a.headers,'content-type':file.type||'application/octet-stream'},body:file}))}
export async function confirmExpenseDocument(documentId:string,draft:ExpenseConfirmDraft,session?:SessionPayload){const a=await authHeaders(session);return parse<{ok:true;cost:{id:string;vehicle_id:string;category:string;supplier?:string|null;amount:number;occurred_on:string}}>(await fetch(`${config.documentsUrl}/expense/confirm`,{method:'POST',headers:a.headers,body:JSON.stringify({document_id:documentId,...draft})}))}
export async function openPrivateDocument(documentId:string,session?:SessionPayload){const target=window.open('about:blank','_blank');try{const a=await authHeaders(session,false),res=await fetch(`${config.documentsUrl}/file?document_id=${encodeURIComponent(documentId)}`,{headers:a.headers,cache:'no-store'});if(!res.ok){await parse(res);return}const blob=await res.blob(),url=URL.createObjectURL(blob);if(target)target.location.href=url;else window.location.href=url;window.setTimeout(()=>URL.revokeObjectURL(url),60_000)}catch(err){target?.close();throw err}}
