import {config} from './config'
import {normalizeVehicleDraft,storageObjectPath,validateVehicleDraft} from '../domain/garage'
import type {CalendarEvent,CalendarEventDraft,Customer,CustomerInteraction,CustomerInteractionDraft,CustomerNextActionDraft,SessionPayload,TenantData,Vehicle,VehicleDraft,VehicleMedia,VehicleWorkItem,WorkItemDraft} from '../types'

const SESSION_KEY='malu23-v2-session'
const MEDIA_BUCKET='dealer-vehicle-media'
const MAX_MEDIA_BYTES=15*1024*1024
const ALLOWED_MEDIA_TYPES=new Set(['image/jpeg','image/png','image/webp','image/heic','image/heif'])
const FINANCE_ROLES=new Set(['ADMIN','AMMINISTRAZIONE'])
const GARAGE_WRITE_ROLES=new Set(['ADMIN','VENDITORE','OPERATORE'])
const CUSTOMER_WRITE_ROLES=new Set(['ADMIN','VENDITORE'])
const CALENDAR_WRITE_ROLES=new Set(['ADMIN','VENDITORE','AMMINISTRAZIONE','OPERATORE'])
const CUSTOMER_CHANNELS=new Set(['TELEFONO','WHATSAPP','EMAIL','VISITA','TEST_DRIVE','NOTE'])
const CALENDAR_EVENT_TYPES=new Set(['APPOINTMENT','CALLBACK','TEST_DRIVE','DELIVERY','PAYMENT','DOCUMENT','WORK','OTHER'])
const CALENDAR_PRIORITIES=new Set(['LOW','NORMAL','HIGH'])
const mediaUrlCache=new Map<string,string>()
const emptyData:TenantData={vehicles:[],media:[],workItems:[],customers:[],customerInteractions:[],customerInterests:[],calendarEvents:[],contracts:[],financials:[],costs:[],invoices:[]}
function jsonHeaders(extra:Record<string,string>={}){return {'content-type':'application/json',...extra}}
async function parse<T>(res:Response):Promise<T>{const text=await res.text();let data:unknown=null;try{data=text?JSON.parse(text):null}catch{data=text}if(!res.ok){const d=data as {message?:string;error_description?:string;error?:string}|null;throw new Error(d?.message||d?.error_description||d?.error||`http_${res.status}`)}return data as T}
export function getSession():SessionPayload|null{try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
export function setSession(session:SessionPayload|null){if(session)localStorage.setItem(SESSION_KEY,JSON.stringify(session));else localStorage.removeItem(SESSION_KEY);window.dispatchEvent(new CustomEvent('malu23:v2-session'))}
export function clearMediaUrlCache(){for(const url of mediaUrlCache.values())URL.revokeObjectURL?.(url);mediaUrlCache.clear()}
export function logout(){clearMediaUrlCache();setSession(null)}
export function canSeeFinance(session:SessionPayload|null){if(!session||session.profile.role==='VENDITORE')return false;const p=session.profile.permissions||{};return FINANCE_ROLES.has(session.profile.role)||p.finance_view===true||p.view_costs===true||p.invoices_view===true}
export function canWriteGarage(session:SessionPayload|null){if(!session)return false;return GARAGE_WRITE_ROLES.has(session.profile.role)||session.profile.permissions?.garage_write===true}
export function canWriteCustomers(session:SessionPayload|null){if(!session)return false;return CUSTOMER_WRITE_ROLES.has(session.profile.role)||session.profile.permissions?.customers_write===true}
export function canWriteCalendar(session:SessionPayload|null){if(!session)return false;return CALENDAR_WRITE_ROLES.has(session.profile.role)||session.profile.permissions?.calendar_write===true}
function requireGarageWrite(session:SessionPayload|null){if(!canWriteGarage(session))throw new Error('garage_write_forbidden')}
function requireCustomerWrite(session:SessionPayload|null){if(!canWriteCustomers(session))throw new Error('customers_write_forbidden')}
function requireCalendarWrite(session:SessionPayload|null){if(!canWriteCalendar(session))throw new Error('calendar_write_forbidden')}
export async function login(identifier:string,password:string,dealerSlug=config.defaultDealerSlug){const data=await parse<SessionPayload>(await fetch(`${config.workerUrl}/auth/resolve-login`,{method:'POST',headers:jsonHeaders(),body:JSON.stringify({identifier:identifier.trim(),dealer_slug:dealerSlug,password})}));if(data.profile.force_password_change)throw new Error('Cambio password obbligatorio: completa prima l’accesso nella versione attuale.');setSession(data);return data}
async function refresh(session:SessionPayload){const data=await parse<SessionPayload & {expires_in?:number}>(await fetch(`${config.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:jsonHeaders({apikey:config.supabasePublishableKey}),body:JSON.stringify({refresh_token:session.refresh_token})}));const next={...session,...data,expires_at:Math.floor(Date.now()/1000)+(data.expires_in||3600)};setSession(next);return next}
async function liveSession(){let session=getSession();if(!session)throw new Error('session_required');if(!session.expires_at||Date.now()/1000>session.expires_at-30)session=await refresh(session);return session}
async function rest<T>(path:string){const session=await liveSession();return parse<T>(await fetch(`${config.supabaseUrl}/rest/v1/${path}`,{headers:{apikey:config.supabasePublishableKey,authorization:`Bearer ${session.access_token}`,accept:'application/json'}}))}
async function restWrite<T>(path:string,{method='POST',body,prefer='return=representation'}:{method?:'POST'|'PATCH'|'DELETE';body?:unknown;prefer?:string}={}){const session=await liveSession();const headers:Record<string,string>={apikey:config.supabasePublishableKey,authorization:`Bearer ${session.access_token}`,accept:'application/json',Prefer:prefer};if(body!==undefined)headers['content-type']='application/json';return parse<T>(await fetch(`${config.supabaseUrl}/rest/v1/${path}`,{method,headers,body:body===undefined?undefined:JSON.stringify(body)}))}
function first<T>(rows:T[],message='write_not_persisted'){if(!rows?.length)throw new Error(message);return rows[0]}
function encodedObjectPath(path:string){return path.split('/').map(encodeURIComponent).join('/')}
async function storageRequest(path:string,method:'GET'|'POST'|'DELETE',body?:Blob){const session=await liveSession();const mode=method==='GET'?'authenticated':'';const prefix=mode?`object/${mode}/${MEDIA_BUCKET}`:`object/${MEDIA_BUCKET}`;const headers:Record<string,string>={apikey:config.supabasePublishableKey,authorization:`Bearer ${session.access_token}`};if(body){headers['content-type']=body.type||'application/octet-stream';headers['x-upsert']='false'}const res=await fetch(`${config.supabaseUrl}/storage/v1/${prefix}/${encodedObjectPath(path)}`,{method,headers,body});if(!res.ok){let message=`storage_${res.status}`;try{const data=await res.json() as {message?:string;error?:string};message=data.message||data.error||message}catch{}throw new Error(message)}return res}

export async function fetchTenantData(session=getSession()):Promise<TenantData>{if(!session)return emptyData;const id=encodeURIComponent(session.dealer.id);const finance=canSeeFinance(session);const [vehicles,media,workItems,customers,customerInteractions,customerInterests,calendarEvents,contracts,financials,costs,invoices]=await Promise.all([
  rest<TenantData['vehicles']>(`vehicles?dealer_id=eq.${id}&deleted_at=is.null&select=*&order=created_at.desc`),
  rest<TenantData['media']>(`vehicle_media?dealer_id=eq.${id}&select=*&order=sort_order.asc,created_at.asc`),
  rest<TenantData['workItems']>(`vehicle_work_items?dealer_id=eq.${id}&select=*&order=created_at.desc`),
  rest<TenantData['customers']>(`customers?dealer_id=eq.${id}&deleted_at=is.null&select=*&order=updated_at.desc`),
  rest<TenantData['customerInteractions']>(`customer_interactions?dealer_id=eq.${id}&select=*&order=happened_at.desc`),
  rest<TenantData['customerInterests']>(`customer_vehicle_interests?dealer_id=eq.${id}&select=*`),
  rest<TenantData['calendarEvents']>(`calendar_events?dealer_id=eq.${id}&status=neq.CANCELLED&select=*&order=starts_at.asc`),
  rest<TenantData['contracts']>(`contracts?dealer_id=eq.${id}&select=*&order=contract_date.desc`),
  finance?rest<TenantData['financials']>(`vehicle_financials?dealer_id=eq.${id}&select=*`):Promise.resolve([]),
  finance?rest<TenantData['costs']>(`vehicle_costs?dealer_id=eq.${id}&select=*`):Promise.resolve([]),
  finance?rest<TenantData['invoices']>(`invoices?dealer_id=eq.${id}&deleted_at=is.null&select=*&order=issue_date.desc`):Promise.resolve([])
]);return {vehicles,media,workItems,customers,customerInteractions,customerInterests,calendarEvents,contracts,financials,costs,invoices}}

/** Non-financial dealer-scoped sales and vehicle availability snapshot. */
export async function fetchSaleOperationsSnapshot(expected:SessionPayload){
 const session=await liveSession()
 if(session.dealer.id!==expected.dealer.id||session.user?.id!==expected.user?.id)throw new Error('Sessione cambiata')
 const dealer=encodeURIComponent(session.dealer.id)
 const [vehicles,contracts]=await Promise.all([
  rest<TenantData['vehicles']>(`vehicles?dealer_id=eq.${dealer}&deleted_at=is.null&select=id,dealer_id,status,deleted_at,updated_at`),
  rest<TenantData['contracts']>(`contracts?dealer_id=eq.${dealer}&template_code=eq.VENDITA&select=id,dealer_id,vehicle_id,customer_id,template_code,status,sale_stage,reservation_expires_at,updated_at`)
 ])
 if(!Array.isArray(vehicles)||!Array.isArray(contracts)||vehicles.some(v=>v.dealer_id!==session.dealer.id)
  ||contracts.some(c=>c.dealer_id!==session.dealer.id||c.template_code!=='VENDITA'))throw new Error('Risposta sincronizzazione non valida')
 return {vehicles,contracts}
}

export async function saveVehicle(draft:Partial<VehicleDraft>,vehicleId?:string){const session=await liveSession();requireGarageWrite(session);const check=validateVehicleDraft(draft);if(!check.valid)throw new Error(check.errors[0]);const payload={...normalizeVehicleDraft(check.value),updated_at:new Date().toISOString()};if(vehicleId){const rows=await restWrite<Vehicle[]>(`vehicles?id=eq.${encodeURIComponent(vehicleId)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:payload});return first(rows,'vehicle_update_not_persisted')}const rows=await restWrite<Vehicle[]>('vehicles',{method:'POST',body:{...payload,dealer_id:session.dealer.id}});return first(rows,'vehicle_create_not_persisted')}

/** Read only operational delivery checks for this dealer/vehicle, without finance access. */
export async function fetchDeliveryChecklistSnapshot(vehicleId:string,expected:SessionPayload):Promise<VehicleWorkItem[]>{
 const session=await liveSession()
 if(session.dealer.id!==expected.dealer.id||session.user?.id!==expected.user?.id)
  throw new Error('Sessione cambiata: ricarica la vendita')
 const dealer=encodeURIComponent(session.dealer.id),vehicle=encodeURIComponent(vehicleId)
 const rows=await rest<VehicleWorkItem[]>(`vehicle_work_items?dealer_id=eq.${dealer}&vehicle_id=eq.${vehicle}&category=eq.CONSEGNA&select=*&order=created_at.desc`)
 if(!Array.isArray(rows)||rows.some(row=>row.dealer_id!==session.dealer.id||row.vehicle_id!==vehicle||String(row.category||'').toUpperCase()!=='CONSEGNA'))
  throw new Error('Risposta sincronizzazione non valida')
 return rows
}
export async function saveWorkItem(vehicleId:string,draft:WorkItemDraft){const session=await liveSession();requireGarageWrite(session);const title=String(draft.title||'').trim();if(!title)throw new Error('Titolo lavoro obbligatorio');const body={dealer_id:session.dealer.id,vehicle_id:vehicleId,title,category:draft.category||'PREPARAZIONE',status:'TODO',priority:draft.priority||'NORMAL',due_date:draft.due_date||null,note:String(draft.note||'').trim()||null,updated_at:new Date().toISOString()};return first(await restWrite<VehicleWorkItem[]>('vehicle_work_items',{method:'POST',body}),'work_item_create_not_persisted')}
export async function reopenDeliveryWorkItem(item:VehicleWorkItem){
 const session=await liveSession()
 requireGarageWrite(session)
 if(item.dealer_id!==session.dealer.id||String(item.category||'').toUpperCase()!=='CONSEGNA'||String(item.status||'').toUpperCase()!=='DONE'||!item.id||!item.vehicle_id||!item.title?.trim())
  throw new Error('Verifica consegna non modificabile')
 const scoped=['id=eq.'+encodeURIComponent(item.id),'dealer_id=eq.'+encodeURIComponent(session.dealer.id),
  'vehicle_id=eq.'+encodeURIComponent(item.vehicle_id),'category=eq.CONSEGNA','status=eq.DONE',
  'title=eq.'+encodeURIComponent(item.title)]
 const now=new Date().toISOString()
 const rows=await restWrite<VehicleWorkItem[]>('vehicle_work_items?'+scoped.join('&'),{method:'PATCH',body:{status:'TODO',completed_at:null,updated_at:now}})
 return first(rows,'La verifica è stata modificata da un altro operatore. Ricarica e riprova.')
}
export async function completeWorkItem(item:VehicleWorkItem){const session=await liveSession();requireGarageWrite(session);const rows=await restWrite<VehicleWorkItem[]>(`vehicle_work_items?id=eq.${encodeURIComponent(item.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{status:'DONE',completed_at:new Date().toISOString(),updated_at:new Date().toISOString()}});return first(rows,'work_item_update_not_persisted')}

export async function saveCustomerNextAction(customer:Customer,draft:CustomerNextActionDraft){const session=await liveSession();requireCustomerWrite(session);const nextStep=String(draft.nextStep||'').trim();if(!nextStep)throw new Error('Inserisci la prossima azione');const rows=await restWrite<Customer[]>(`customers?id=eq.${encodeURIComponent(customer.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{next_step:nextStep,next_contact_at:draft.nextContactAt||null,updated_at:new Date().toISOString()}});return first(rows,'customer_next_action_not_persisted')}
export async function clearCustomerNextAction(customer:Customer){const session=await liveSession();requireCustomerWrite(session);const rows=await restWrite<Customer[]>(`customers?id=eq.${encodeURIComponent(customer.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{next_step:null,next_contact_at:null,updated_at:new Date().toISOString()}});return first(rows,'customer_next_action_not_cleared')}
export async function clearMatchingReservationCallback(customer:Customer,expectedNextStep:string){
 const session=await liveSession()
 requireCustomerWrite(session)
 if(!expectedNextStep.startsWith('Ricontatto prenotazione ')||customer.next_step!==expectedNextStep)throw new Error('Il richiamo CRM non corrisponde alla prenotazione')
 const contactAt=customer.next_contact_at
 const filter=contactAt?'next_contact_at=eq.'+encodeURIComponent(contactAt):'next_contact_at=is.null'
 const rows=await restWrite<Customer[]>(
  'customers?id=eq.'+encodeURIComponent(customer.id)+'&dealer_id=eq.'+encodeURIComponent(session.dealer.id)+'&next_step=eq.'+encodeURIComponent(expectedNextStep)+'&'+filter,
  {method:'PATCH',body:{next_step:null,next_contact_at:null,updated_at:new Date().toISOString()}}
 )
 if(!rows?.length)throw new Error('Il richiamo è stato aggiornato da un altro operatore. Ricarica il CRM.')
 return rows[0]
}
export async function logCustomerInteraction(customer:Customer,draft:CustomerInteractionDraft){const session=await liveSession();requireCustomerWrite(session);const title=String(draft.title||'').trim();const channel=String(draft.channel||'NOTE').toUpperCase();if(!title)throw new Error('Descrizione contatto obbligatoria');if(!CUSTOMER_CHANNELS.has(channel))throw new Error('Canale contatto non valido');return first(await restWrite<CustomerInteraction[]>('customer_interactions',{method:'POST',body:{dealer_id:session.dealer.id,customer_id:customer.id,channel,title,happened_at:new Date().toISOString(),created_by:session.user?.id||null,updated_at:new Date().toISOString()}}),'customer_interaction_not_persisted')}

export async function saveCalendarEvent(draft:CalendarEventDraft){const session=await liveSession();requireCalendarWrite(session);const title=String(draft.title||'').trim();const eventType=String(draft.eventType||'APPOINTMENT').toUpperCase();const priority=String(draft.priority||'NORMAL').toUpperCase();if(!title)throw new Error('Titolo appuntamento obbligatorio');if(!draft.startsAt||Number.isNaN(new Date(draft.startsAt).getTime()))throw new Error('Data appuntamento non valida');if(!CALENDAR_EVENT_TYPES.has(eventType))throw new Error('Tipo appuntamento non valido');if(!CALENDAR_PRIORITIES.has(priority))throw new Error('Priorità appuntamento non valida');return first(await restWrite<CalendarEvent[]>('calendar_events',{method:'POST',body:{dealer_id:session.dealer.id,event_type:eventType,title,starts_at:new Date(draft.startsAt).toISOString(),all_day:Boolean(draft.allDay),status:'OPEN',priority,customer_id:draft.customerId||null,vehicle_id:draft.vehicleId||null,note:String(draft.note||'').trim()||null,source:'MANUAL',created_by:session.user?.id||null,updated_at:new Date().toISOString()}}),'calendar_event_not_persisted')}
export async function completeCalendarEvent(event:CalendarEvent){const session=await liveSession();requireCalendarWrite(session);const rows=await restWrite<CalendarEvent[]>(`calendar_events?id=eq.${encodeURIComponent(event.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{status:'DONE',updated_at:new Date().toISOString()}});return first(rows,'calendar_event_not_completed')}

export async function getPrivateMediaObjectUrl(objectKey:string){const hit=mediaUrlCache.get(objectKey);if(hit)return hit;const res=await storageRequest(objectKey,'GET');const blob=await res.blob();const url=URL.createObjectURL(blob);mediaUrlCache.set(objectKey,url);return url}

export async function uploadVehiclePhotos(vehicle:Vehicle,files:File[],existingMedia:VehicleMedia[]=[]){const session=await liveSession();requireGarageWrite(session);const photoFiles=files.filter(Boolean);if(!photoFiles.length)return [] as VehicleMedia[];const currentPhotos=existingMedia.filter(m=>(m.kind||'PHOTO')==='PHOTO');const uploaded:VehicleMedia[]=[];for(const [index,file] of photoFiles.entries()){if(!ALLOWED_MEDIA_TYPES.has(file.type))throw new Error(`Formato foto non supportato: ${file.type||file.name}`);if(file.size>MAX_MEDIA_BYTES)throw new Error('Una foto supera il limite di 15 MB');const mediaId=crypto.randomUUID();const path=storageObjectPath(session.dealer.id,vehicle.id,mediaId,file.name||`foto-${index+1}`,file.type);await storageRequest(path,'POST',file);const isCover=currentPhotos.length===0&&uploaded.length===0;try{const row=first(await restWrite<VehicleMedia[]>('vehicle_media',{method:'POST',body:{id:mediaId,dealer_id:session.dealer.id,vehicle_id:vehicle.id,kind:'PHOTO',object_key:path,caption:file.name||null,sort_order:currentPhotos.length+uploaded.length,is_cover:isCover,updated_at:new Date().toISOString()}}),'vehicle_media_create_not_persisted');uploaded.push(row);if(isCover)await restWrite<Vehicle[]>(`vehicles?id=eq.${encodeURIComponent(vehicle.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{cover_object_key:path,updated_at:new Date().toISOString()}})}catch(err){try{await storageRequest(path,'DELETE')}catch{}throw err}}return uploaded}

export async function setVehicleCover(vehicle:Vehicle,media:VehicleMedia){const session=await liveSession();requireGarageWrite(session);await restWrite<VehicleMedia[]>(`vehicle_media?vehicle_id=eq.${encodeURIComponent(vehicle.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{is_cover:false,updated_at:new Date().toISOString()}});await restWrite<VehicleMedia[]>(`vehicle_media?id=eq.${encodeURIComponent(media.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{is_cover:true,updated_at:new Date().toISOString()}});await restWrite<Vehicle[]>(`vehicles?id=eq.${encodeURIComponent(vehicle.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{cover_object_key:media.object_key,updated_at:new Date().toISOString()}})}

export async function deleteVehiclePhoto(vehicle:Vehicle,media:VehicleMedia,siblings:VehicleMedia[]){const session=await liveSession();requireGarageWrite(session);await restWrite<VehicleMedia[]>(`vehicle_media?id=eq.${encodeURIComponent(media.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'DELETE'});try{await storageRequest(media.object_key,'DELETE')}catch(err){console.warn('Orphan vehicle media object',media.object_key,err)}const cached=mediaUrlCache.get(media.object_key);if(cached){URL.revokeObjectURL?.(cached);mediaUrlCache.delete(media.object_key)}if(media.is_cover||vehicle.cover_object_key===media.object_key){const next=siblings.find(x=>x.id!==media.id&&(x.kind||'PHOTO')==='PHOTO');if(next)await setVehicleCover(vehicle,next);else await restWrite<Vehicle[]>(`vehicles?id=eq.${encodeURIComponent(vehicle.id)}&dealer_id=eq.${encodeURIComponent(session.dealer.id)}`,{method:'PATCH',body:{cover_object_key:null,updated_at:new Date().toISOString()}})}}
